package com.clothingstore;
import jakarta.persistence.*;
@Entity @Table(name="users") public class UserAccount { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="full_name") private String fullName; private String email; @Column(name="password_hash") private String passwordHash; private String role; private boolean enabled=true; public Long getId(){return id;} public String getFullName(){return fullName;} public String getEmail(){return email;} public String getPasswordHash(){return passwordHash;} public String getRole(){return role;} public boolean isEnabled(){return enabled;} public void setFullName(String v){fullName=v;} public void setEmail(String v){email=v.toLowerCase();} public void setPasswordHash(String v){passwordHash=v;} public void setRole(String v){role=v;} }
